mapper.select:
SELECT id, tenant_id, period_start, period_end, token_total, cost_amount, currency, status
FROM billing_record
WHERE tenant_id = #{tenantId}
  AND period_start = #{periodStart}
  AND period_end = #{periodEnd}

mapper.update:
UPDATE billing_record
SET status = 'CONFIRMED'
WHERE tenant_id = #{tenantId}
  AND period_start = #{periodStart}
  AND period_end = #{periodEnd}
  AND status = 'DRAFT'

UPDATE billing_record
SET status = 'INVOICED'
WHERE tenant_id = #{tenantId}
  AND period_start = #{periodStart}
  AND period_end = #{periodEnd}
  AND status = 'CONFIRMED'

UPDATE billing_record
SET status = 'PAID'
WHERE tenant_id = #{tenantId}
  AND period_start = #{periodStart}
  AND period_end = #{periodEnd}
  AND status = 'INVOICED'
